class BillingClientHolder(context: Context) {
    private val client = BillingClient.newBuilder(context)
        .setListener { _, result -> handlePurchaseResult(result) }
        .enablePendingPurchases()
        .build()

    fun queryAndBuy(activity: Activity, productId: String) {
        client.startConnection {
            if (!isReady) return@startConnection
            val params = QueryProductDetailsParams.newBuilder()
                .setProductList(
                    listOf(
                        QueryProductDetailsParams.Product.newBuilder()
                            .setProductId(productId)
                            .setProductType(BillingClient.ProductType.SUBS)
                            .build()
                    )
                )
                .build()
            client.queryProductDetailsAsync(params) { result, details ->
                val product = details?.firstOrNull()
                if (result.responseCode == BillingClient.BillingResponseCode.OK && product != null) {
                    val flow = BillingFlowParams.newBuilder()
                        .setProductDetailsParamsList(
                            listOf(
                                BillingFlowParams.ProductDetailsParams.newBuilder()
                                    .setProductDetails(product)
                                    .build()
                            )
                        )
                        .build()
                    client.launchBillingFlow(activity, flow)
                }
            }
        }
    }
}

class UpdateAndReviewManager(private val context: Context) {
    private val appUpdateManager = AppUpdateManagerFactory.create(context)
    private val reviewManager = ReviewManagerFactory.create(context)

    fun checkForUpdate(activity: Activity) {
        appUpdateManager.appUpdateInfo.addOnSuccessListener { info ->
            if (info.updateAvailability() == UpdateAvailability.UPDATE_AVAILABLE
                && info.isUpdateTypeAllowed(AppUpdateType.FLEXIBLE)
            ) {
                appUpdateManager.startUpdateFlowForResult(
                    info, AppUpdateType.FLEXIBLE, activity, REQUEST_CODE_UPDATE
                )
            }
        }
    }

    fun onActivityResult(requestCode: Int, resultCode: Int) {
        if (requestCode == REQUEST_CODE_UPDATE && resultCode != Activity.RESULT_OK) {
            resurfaceLater()
        }
    }

    fun requestRating(activity: Activity) {
        reviewManager.requestReviewFlow().addOnCompleteListener { task ->
            if (task.isSuccessful) {
                reviewManager.launchReviewFlow(activity, task.result)
            }
        }
    }

    private fun resurfaceLater() = Unit

    companion object {
        private const val REQUEST_CODE_UPDATE = 9001
    }
}

class ChessFeatureInstaller(
    private val context: Context,
    private val activity: Activity
) {
    private val manager = SplitInstallManagerFactory.create(context)
    private val listener = SplitInstallStateUpdatedListener { state ->
        when (state.status()) {
            SplitInstallSessionStatus.INSTALLED -> loadChessScreen()
            SplitInstallSessionStatus.REQUIRES_USER_CONFIRMATION ->
                manager.startConfirmationDialogForResult(state, activity, REQUEST_CONFIRM)
            SplitInstallSessionStatus.FAILED -> notifyUser("Couldn't install chess")
        }
    }

    fun install() {
        manager.registerListener(listener)
        val request = SplitInstallRequest.newBuilder().addModule("chess").build()
        manager.startInstall(request).addOnFailureListener {
            notifyUser("Couldn't install chess")
        }
    }

    fun cleanup() = manager.unregisterListener(listener)

    private fun loadChessScreen() {
        val intent = Intent().setClassName(context, "com.example.chess.ChessActivity")
        activity.startActivity(intent)
    }

    private fun notifyUser(message: String) {
        Toast.makeText(context, message, Toast.LENGTH_SHORT).show()
    }

    companion object {
        private const val REQUEST_CONFIRM = 1001
    }
}

