fun verify16KbPageAlignment(apk: File, zipalign: File) {
    val exit = ProcessBuilder(
        zipalign.absolutePath, "-c", "-P", "16", "4", apk.absolutePath
    ).start().waitFor()
    check(exit == 0) { "APK $apk is not 16 KB page-aligned" }
}

class CrashlyticsReporter {
    fun report(crash: ReportedCrash) {
        FirebaseCrashlytics.getInstance().apply {
            setUserId(crash.userId ?: "anonymous")
            setCustomKey("screen", crash.screen)
            setCustomKey("flavor", BuildConfig.FLAVOR)
            log("crash context: plan=${crash.planId}, offline=${crash.wasOffline}")
            recordException(crash.throwable)
        }
    }

    fun setConsent(optedIn: Boolean) {
        FirebaseCrashlytics.getInstance().setDataCollectionEnabled(optedIn)
    }
}

@SuppressLint("MissingPermission")
fun readAdvertisingId(context: Context): String? {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        val granted = ContextCompat.checkSelfPermission(
            context, Manifest.permission.ACCESS_ADSERVICES_AD_ID
        ) == PackageManager.PERMISSION_GRANTED
        if (!granted) return null
    }
    val info = AdvertisingIdClient.getAdvertisingIdInfo(context)
    return if (info.isLimitAdTrackingEnabled) "" else info.id
}

